fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, w / 2 - 16);
        host::display::state_set(2, h / 2 - 16);
    }
    if host::display::pointer_down() == 1 {
        host::display::state_set(1, host::display::pointer_x() - 16);
        host::display::state_set(2, host::display::pointer_y() - 16);
    }
    host::display::clear(0x000000);
    host::display::fill_rect(host::display::state_get(1), host::display::state_get(2), 32, 32, 0xff00ff);
    host::display::present();
}
